function Read-Hidden([string]$Label){$s=Read-Host $Label -AsSecureString;try{if($s.Length-eq 0){throw 'Value cannot be empty.'};$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}}finally{$s.Dispose()}}
function Send([string]$Action,[object]$Request){$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/rest/v1/rpc/task_dispatch');try{$q.Headers.Add('Content-Profile','reivro_checks_api');$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json @{action=$Action;request=$Request} -Depth 30 -Compress),[Text.Encoding]::UTF8,'application/json');$x=$script:client.SendAsync($q).GetAwaiter().GetResult();try{[pscustomobject]@{Status=[int]$x.StatusCode;Body=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()}}finally{$x.Dispose()}}finally{$q.Dispose()}}
function PsqlJson([string]$File,[hashtable]$Extra){$oldP=$env:PGPASSWORD;$oldC=$env:PGSSLROOTCERT;try{$env:PGPASSWORD=$script:dbPassword;$env:PGSSLROOTCERT=$script:ca;$a=@('-X','-w','-qAt','-v','ON_ERROR_STOP=1','-d','host=aws-1-us-west-1.pooler.supabase.com port=5432 user=postgres.lbklqqqbmeyseeccdqog dbname=postgres sslmode=verify-full','-v',"repository_id=$($script:plan.repository_id)",'-v',"contract_id=$($script:plan.contract_id)",'-v',"submission_id=$($script:plan.submission_id)",'-v',"digest=$($script:plan.digest)",'-v',"base_sha=$($script:plan.base_sha)",'-v',"head_sha=$($script:plan.head_sha)");foreach($k in $Extra.Keys){$a+=@('-v',"$k=$($Extra[$k])")};$a+=@('-f',$File);$o=&$script:psql @a;if($LASTEXITCODE-ne 0){throw "psql exited $LASTEXITCODE"};$z=@($o|Where-Object{$_-match'^\{'});if($z.Count-ne 1){throw 'Expected one reconciliation record.'};$z[0]|ConvertFrom-Json}finally{if($null-eq$oldP){Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue}else{$env:PGPASSWORD=$oldP};if($null-eq$oldC){Remove-Item Env:PGSSLROOTCERT -ErrorAction SilentlyContinue}else{$env:PGSSLROOTCERT=$oldC}}}
function Sha256([string]$Text){$h=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text)))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
$client=$handler=$key=$email=$password=$session=$dbPassword=$approval=$null;$stage='bootstrap';$writeStarted=$false
try{
 $stage='path-plan';if(-not(Test-Path -LiteralPath $Plan -PathType Leaf)){throw 'Private plan file is missing.'};Write-Output 'PASS initialization plan path'
