 $stage='path-ca-certificate';if(-not(Test-Path -LiteralPath $cert -PathType Leaf)){throw 'Configured CA certificate is missing.'};$ca=(Resolve-Path -LiteralPath $cert).Path;Write-Output 'PASS initialization CA certificate'
 $stage='path-private-repository';if(-not(Test-Path -LiteralPath $Repository -PathType Container)){throw 'Private Git repository directory is missing.'};$Repository=(Resolve-Path -LiteralPath $Repository).Path;Write-Output 'PASS initialization private repository path'
 $stage='plan-json';try{$plan=Get-Content -LiteralPath $Plan -Raw|ConvertFrom-Json}catch{throw 'Private plan is not valid JSON.'};Write-Output 'PASS initialization plan JSON'
 $stage='plan-guards'
 if($plan.staging_ref-cne'lbklqqqbmeyseeccdqog'-or[guid]$plan.agent_id-ne[guid]'0dae2b29-adaa-48b6-9a96-e9ac646b2a7a'-or[string]$plan.base_sha-cne'07fc0b907d3aa9659ea7541f80acf6c18586e645'-or[string]$plan.head_sha-cne'e0d50dd239f8c8c3c39df84187741009f7496d09'-or[string]$plan.digest-cnotmatch'^[0-9a-f]{64}$'){throw 'Private plan differs from the approved fixture.'}
 Write-Output 'PASS initialization plan guards'
 $stage='psql-path';$psqlPath=Join-Path $PgBin 'psql.exe';if(-not(Test-Path -LiteralPath $psqlPath -PathType Leaf)){throw 'PostgreSQL psql.exe is missing from configured PgBin.'};$psql=(Resolve-Path -LiteralPath $psqlPath).Path;Write-Output 'PASS initialization psql path'
 $stage='psql-version';$psqlVersion=&$psql --version;if($LASTEXITCODE-ne 0-or$psqlVersion-notmatch'PostgreSQL\)\s+19(?:\.\d+)?(?:\s|$)'){throw 'Configured psql is not PostgreSQL major version 19.'};Write-Output 'PASS initialization PostgreSQL major version 19'
 $stage='git-command';$gitCommand=Get-Command git -CommandType Application -ErrorAction SilentlyContinue;if($null-eq$gitCommand){throw 'Git executable is unavailable.'};$git=$gitCommand.Source;Write-Output 'PASS initialization Git executable'
 $stage='git-worktree';&$git -C $Repository rev-parse --is-inside-work-tree 2>$null|Out-Null;if($LASTEXITCODE-ne 0){throw 'Provided repository is not a Git worktree.'};Write-Output 'PASS initialization Git worktree'
 $stage='git-origin';$origin=(&$git -C $Repository remote get-url origin 2>$null).Trim();if($LASTEXITCODE-ne 0-or$origin-cnotmatch'(?i)(?:github\.com[/:])sovereis/REIVRO(?:\.git)?$'){throw 'Git origin is not the approved private REIVRO repository.'};Write-Output 'PASS initialization approved Git origin'
 $stage='git-kit-commit';$kitCommit=(&$git -C $Repository rev-parse HEAD).Trim();if($LASTEXITCODE-ne 0-or$kitCommit-cnotmatch'^[0-9a-f]{40}$'){throw 'Cannot resolve checked-out kit commit.'};Write-Output 'PASS initialization checked-out kit commit'
 # Every secret and every interactive decision is collected before the final claim.
 $key=(Read-Hidden 'Staging default publishable key').Trim();$email=(Read-Hidden 'Worker A staging email').Trim();$password=Read-Hidden 'Worker A staging password';$dbPassword=Read-Hidden 'Staging PostgreSQL password';if($key-cnotmatch'^sb_publishable_[A-Za-z0-9_-]+$'){throw 'Invalid publishable key.'}
 $approval=Read-Host 'Type STAGING-FINAL-STATIC-EXECUTION-APPROVED';if($approval-cne'STAGING-FINAL-STATIC-EXECUTION-APPROVED'){throw 'Final execution not confirmed.'}
 $stage='Git evidence';&$git -C $Repository cat-file -e "$($plan.base_sha)^{commit}";if($LASTEXITCODE-ne 0){throw 'Approved BASE commit is absent from the private clone.'};&$git -C $Repository cat-file -e "$($plan.head_sha)^{commit}";if($LASTEXITCODE-ne 0){throw 'Approved HEAD commit is absent from the private clone.'};&$git -C $Repository merge-base --is-ancestor $plan.base_sha $plan.head_sha;if($LASTEXITCODE-ne 0){throw 'BASE is not an ancestor of HEAD.'};&$git -C $Repository cat-file -e "$($plan.head_sha):guide.md";if($LASTEXITCODE-ne 0){throw 'guide.md is absent at HEAD.'};$changed=@(&$git -C $Repository diff --name-only $plan.base_sha $plan.head_sha);if($changed.Count-ne 1-or$changed[0]-cne'guide.md'){throw 'Unexpected synthetic diff.'};$blob=(&$git -C $Repository rev-parse "$($plan.head_sha):guide.md").Trim();if($blob-cne'54c1e3abe1648ec0a72636f135f78ffec7e00bcd'){throw 'Unexpected guide.md blob.'}
 $evidenceBody=[ordered]@{kind='git-static-v1';criterion='exists: guide.md';base_sha=[string]$plan.base_sha;head_sha=[string]$plan.head_sha;path='guide.md';blob_sha=$blob;verified=$true};$evidenceJson=ConvertTo-Json $evidenceBody -Compress;$evidenceDigest=Sha256 $evidenceJson;$evidence=[ordered]@{};foreach($k in $evidenceBody.Keys){$evidence[$k]=$evidenceBody[$k]};$evidence.digest=$evidenceDigest;Write-Output 'PASS static Git evidence prepared before claim'
 $stage='database preflight';$scope=PsqlJson $pre @{};if([guid]$scope.worker_id-eq[guid]::Empty-or[guid]$scope.run_id-eq[guid]::Empty-or[guid]$scope.old_attempt_id-eq[guid]::Empty-or(ConvertTo-Json $scope.policy_set -Compress)-cne'[]'){throw 'Final preflight failed.'};Write-Output 'PASS expired fence 2 and journal 18 preflight'
 $stage='Worker login';Add-Type -AssemblyName System.Net.Http;$handler=[Net.Http.HttpClientHandler]::new();$handler.AllowAutoRedirect=$false;$handler.UseCookies=$false;$client=[Net.Http.HttpClient]::new($handler);$client.BaseAddress=[uri]'https://lbklqqqbmeyseeccdqog.supabase.co';$client.Timeout=[TimeSpan]::FromSeconds(12);$client.DefaultRequestHeaders.Add('apikey',$key);$q=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Post,'/auth/v1/token?grant_type=password');try{$q.Content=[Net.Http.StringContent]::new((ConvertTo-Json @{email=$email;password=$password} -Compress),[Text.Encoding]::UTF8,'application/json');$x=$client.SendAsync($q).GetAwaiter().GetResult();try{if(-not$x.IsSuccessStatusCode){throw "Login HTTP $([int]$x.StatusCode)"};$session=$x.Content.ReadAsStringAsync().GetAwaiter().GetResult()|ConvertFrom-Json}finally{$x.Dispose()}}finally{$q.Dispose()};if($session.user.id-cne[string]$scope.worker_id){throw 'Unexpected Worker identity.'};$client.DefaultRequestHeaders.Authorization=[Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$session.access_token);$key=$email=$password=$session=$null;Write-Output 'PASS all credentials Auth and prompts completed before claim'
 $request=@{repository_id=[long]$plan.repository_id;installation_id=[long]$scope.installation_id;repository=[string]$scope.repository;base_ref=[string]$scope.base_ref;id=[string]$plan.submission_id;delivery=[string]$plan.submission_id;pr=1;base_sha=[string]$plan.base_sha;head_sha=[string]$plan.head_sha;digest=[string]$plan.digest;verifier='task-completion-v1'}
 $stage='final claim';$writeStarted=$true;$x=Send 'claim' $request;if($x.Status-lt 200-or$x.Status-ge 300){throw "Claim HTTP $($x.Status)"};$claim=$x.Body|ConvertFrom-Json;if($claim.state-cne'running'-or[guid]$claim.run_id-ne[guid]$scope.run_id-or[int]$claim.fence-ne 3-or[guid]$claim.attempt_id-eq[guid]::Empty-or(ConvertTo-Json $claim.policy_set -Compress)-cne'[]'){throw 'Unexpected final claim receipt or policy drift.'}
 $result=[ordered]@{status='VERIFIED';base_sha=[string]$plan.base_sha;head_sha=[string]$plan.head_sha;digest=[string]$plan.digest;verifier='task-completion-v1';evidence=$evidence;policy_set=$claim.policy_set}
 $finish=@{repository_id=[long]$plan.repository_id;installation_id=[long]$scope.installation_id;id=[string]$plan.submission_id;run_id=[string]$claim.run_id;attempt_id=[string]$claim.attempt_id;fence=3;result=$result}
 $stage='finish';$x=Send 'finish' $finish;if($x.Status-lt 200-or$x.Status-ge 300){throw "Finish HTTP $($x.Status)"};$receipt=$x.Body|ConvertFrom-Json;if($receipt.state-cne'completed'-or$receipt.result.status-cne'VERIFIED'){throw 'Unexpected finish receipt.'}
 $stage='postcheck';$policyJson=ConvertTo-Json $claim.policy_set -Depth 20 -Compress;$saved=PsqlJson $post @{run_id=$claim.run_id;evidence_digest=$evidenceDigest;policy_set=$policyJson};if(-not[bool]$saved.all_checks_pass){throw 'Final persisted state failed reconciliation.'};Write-Output 'PASS task_submissions.result VERIFIED';Write-Output 'PASS runs.outcome INCONCLUSIVE preserved';Write-Output 'PASS fence 3 completed and journal 21 reconciled';Write-Output 'FIRST_CONTROL_PLANE_TASK_COMPLETED_STATIC_ONLY'
}catch{[Console]::Error.WriteLine("FAIL $stage");[Console]::Error.WriteLine("DIAGNOSTIC guard=$stage; details suppressed; no secret values printed");if($writeStarted){[Console]::Error.WriteLine('WRITE MAY HAVE OCCURRED. DO NOT RETRY. READ-ONLY RECONCILIATION FOLLOWS.');try{$r=PsqlJson $reconcile @{};[Console]::Error.WriteLine(('RECONCILIATION '+(ConvertTo-Json $r -Depth 20 -Compress)))}catch{[Console]::Error.WriteLine('READ-ONLY RECONCILIATION FAILED; preserve evidence and stop.')}};exit 1}finally{$key=$email=$password=$session=$dbPassword=$approval=$claim=$receipt=$x=$null;Remove-Item Env:PGPASSWORD,Env:PGSSLROOTCERT -ErrorAction SilentlyContinue;if($null-ne$client){$client.DefaultRequestHeaders.Authorization=$null;$client.Dispose()}elseif($null-ne$handler){$handler.Dispose()}}
